  numb   :["#3A0A2E","#E040A0","#FFD9F0"],  // 폭마   320° 자홍 — 화면에 없던 색
  thunder:["#33200C","#D9A860","#FFF0D0"],  // 뢰명 40° 황동 — 종의 색
  murk   :["#26300E","#A8C43C","#EEFFC0"],
