    const draw=(cc)=>{
      fillPoly(cc,jagPoly(x,y,rr,6,sd,1.25),A(TX[0],Math.max(0,al*.95)));
      fillPoly(cc,jagPoly(x,y,rr*.55,6,sd+1.1,1.2),A(TX[1],Math.max(0,al*.80)));};
