  // 공명에 「마법진」을 붙이면 「마법진 하나 = 광주」 단언이 깨진다.
  brand:["마법"], spore:["마법"], chime:["마법"],
  // 특수 속성·시안 계열
  mgNovaDusk:["마법","오라"], mgNovaSplit:["마법","일반"],
  mgNovaDetonate:["일반"], JDlatch:["마법","일반"],
  // 일반 — 총구에서 곧장 나간다
