  tether  :[.26,.30,.78,.32,.24],    // 1.90  발현 안에서 조임 .60 → **당김 .18**
  skewer  :[.34,.26,.34,.38,.28],    // 1.60  발현이 짧다 — 꿰는 것은 순간이다
  hammer  :[.44,.62,.30,.50,.34],    // 2.20  생성이 제일 길다(망치를 짠다).
