const VLTsPRE = .42, VLTsRISE = .24, VLTsHOLD = 2.58, VLTsFADE = .42, VLTsEND = .34;
const VLTsLIFE = VLTsRISE + VLTsHOLD + VLTsFADE;      // 3.24 = .18 × 18
const VLTsPER = VLTsPRE + VLTsLIFE + VLTsEND;         // 4.00
const VLTsCRAWL = 1.10, VLTsTICK = .18;
