const VLTsR = 64, VLTsW = 13;
/// ① 기는 전류 가닥 · ② 빗장(L2+) · ③ 모서리 침(L3+) · ④ 살(L4+)
const VLTsSTR = [2, 2, 3, 3, 4];
const VLTsBAR = [0, 6, 6, 8, 8];
const VLTsBARB = [0, 0, 10, 12, 14];
