const FQRC_F = [[-40, -80, 10], [58, -30, 11], [-70, -26, 10], [24, -104, 9]];
const FQRC_PER = 2.40;                        // 한 바퀴(초)
const FQRC_T = [.120, .225, .800, .915];      // 앞 네 마디가 끝나는 자리
const FQRC_N = [2, 3, 3, 4, 4];               // 꺾이는 수
const FQRC_MARK = [0, 0, 1, 1, 1];            // 꺾인 자리에 자국이 남나
const FQRC_AWK = [0, 0, 0, 0, 1];             // 각성 — 흰 심 + 마지막 터짐이 다단
